// Two payload shapes: a failed execution (execution.*) and a trigger that couldn't start (trigger.*, no execution id).
const j = $input.first().json;
const ex = j.execution || {};
const tr = j.trigger || {};
const wf = j.workflow || {};
const err = ex.error || tr.error || {};
let message = String(err.message || 'Unknown error').trim();
if (err.description && !message.includes(err.description)) message += ' ' + String(err.description).trim();
return [{ json: {
  workflow_id: String(wf.id || ''),
  workflow_name: wf.name || 'Unknown workflow',
  execution_id: ex.id ? String(ex.id) : '',
  execution_url: ex.url || '',
  node_name: ex.lastNodeExecuted || (err.node && err.node.name) || (tr.error && tr.error.node && tr.error.node.name) || '',
  error_message: message.replace(/\s+/g, ' ').slice(0, 2000),
  mode: ex.id ? (ex.mode || 'trigger') : 'activation',
  failed_at: $now.toISO(),
} }];

// Works out how often each published workflow should run, from its Schedule Trigger.
// Why Code: no node parses a schedule rule or a cron expression.
const s = $('Watch settings').first().json;
const self = $workflow.id;
const rows = {};
for (const { json: r } of $('Get watch rows').all()) if (r && r.workflow_id) rows[String(r.workflow_id)] = r;

const DAY = 1440;
const fmt = m => m >= DAY ? (m % DAY ? Math.round(m / 60) + ' h' : (m / DAY) + (m === DAY ? ' day' : ' days')) : m >= 60 ? (m % 60 ? Math.floor(m / 60) + ' h ' + (m % 60) + ' min' : (m / 60) + ' h') : m + ' min';

function expand(field, lo, hi, names = []) {
  const set = new Set();
  for (let part of String(field).toUpperCase().split(',')) {
    names.forEach((n, i) => { part = part.replace(new RegExp('\\b' + n + '\\b', 'g'), String(i + lo)); });
    let [range, step] = part.split('/');
    step = step ? Number(step) : 1;
    let a = lo, b = hi;
    if (range !== '*' && range !== '?') {
      const m = range.match(/^(\d+)(?:-(\d+))?$/);
      if (!m) return null;
      a = Number(m[1]); b = m[2] !== undefined ? Number(m[2]) : (step > 1 ? hi : a);
    }
    for (let v = a; v <= b; v += step) set.add(v);
  }
  return set;
}

function cronGap(expr) {
  let f = String(expr || '').trim().split(/\s+/);
  if (f.length === 6) f = f.slice(1);              // n8n allows a seconds field first
  if (f.length !== 5) return null;
  const min = expand(f[0], 0, 59), hour = expand(f[1], 0, 23), dom = expand(f[2], 1, 31);
  const mon = expand(f[3], 1, 12, ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC']);
  const dow = expand(f[4].replace(/\b7\b/g, '0'), 0, 6, ['SUN','MON','TUE','WED','THU','FRI','SAT']);
  if (!min || !hour || !dom || !mon || !dow) return null;
  const domAny = f[2] === '*' || f[2] === '?', dowAny = f[4] === '*' || f[4] === '?';
  const times = [];
  const start = Date.UTC(2026, 0, 5);                // any Monday; 62 days covers monthly schedules
  for (let d = 0; d < 62; d++) {
    const day = new Date(start + d * 864e5);
    if (!mon.has(day.getUTCMonth() + 1)) continue;
    const okDom = dom.has(day.getUTCDate()), okDow = dow.has(day.getUTCDay());
    if (!(domAny && dowAny ? true : domAny ? okDow : dowAny ? okDom : (okDom || okDow))) continue;
    for (const h of [...hour].sort((a, b) => a - b)) for (const m of [...min].sort((a, b) => a - b)) times.push(d * DAY + h * 60 + m);
  }
  if (times.length < 2) return null;
  let gap = 0;
  for (let i = 1; i < times.length; i++) gap = Math.max(gap, times[i] - times[i - 1]);
  return gap;
}

function ruleGap(iv) {
  const field = iv.field || 'days';
  if (field === 'cronExpression') return { gap: cronGap(iv.expression), text: 'cron ' + iv.expression };
  if (field === 'seconds') return { gap: 1, text: 'every ' + (iv.secondsInterval || 30) + ' s' };
  if (field === 'minutes') { const n = iv.minutesInterval || 5; return { gap: n, text: 'every ' + fmt(n) }; }
  if (field === 'hours') { const n = (iv.hoursInterval || 1) * 60; return { gap: n, text: 'every ' + fmt(n) }; }
  if (field === 'days') { const n = (iv.daysInterval || 1); return { gap: n * DAY, text: n === 1 ? 'daily' : 'every ' + n + ' days' }; }
  if (field === 'weeks') {
    const n = iv.weeksInterval || 1;
    const days = [...new Set((iv.triggerAtDay && iv.triggerAtDay.length ? iv.triggerAtDay : [0]).map(Number))].sort((a, b) => a - b);
    if (n > 1 || days.length === 1) return { gap: n * 7 * DAY, text: n > 1 ? 'every ' + n + ' weeks' : 'weekly' };
    let gap = 0;
    for (let i = 0; i < days.length; i++) gap = Math.max(gap, ((days[(i + 1) % days.length] - days[i] + 7) % 7 || 7) * DAY);
    return { gap, text: days.length === 5 && days.join() === '1,2,3,4,5' ? 'weekdays' : days.length + ' days a week' };
  }
  if (field === 'months') { const n = iv.monthsInterval || 1; return { gap: n * 31 * DAY, text: n === 1 ? 'monthly' : 'every ' + n + ' months' }; }
  return { gap: null, text: field };
}

const out = [];
for (const { json: w } of $('Get published workflows').all()) {
  if (!w || !w.id || w.id === self) continue;
  const tags = (w.tags || []).map(t => t.name);
  if (s.ignore_tag && tags.includes(s.ignore_tag)) continue;
  const row = rows[String(w.id)] || {};
  if (row.enabled === false) continue;
  const override = Number(row.override_gap_minutes) > 0 ? Number(row.override_gap_minutes) : null;
  const triggers = (w.nodes || []).filter(n => n.type === 'n8n-nodes-base.scheduleTrigger' && !n.disabled);
  if (!triggers.length && !override) continue;      // webhook-only: Catch still sees its failures
  let gap = null; const texts = [];
  for (const t of triggers) for (const iv of ((t.parameters.rule || {}).interval || [{}])) {
    const r = ruleGap(iv); texts.push(r.text);
    if (r.gap) gap = gap === null ? r.gap : Math.min(gap, r.gap);
  }
  const inferred = gap ? Math.round(gap + Math.max(s.grace_min_minutes, gap * s.grace_ratio)) : null;
  out.push({ json: {
    workflow_id: String(w.id), workflow_name: w.name, schedule: texts.join(', ') || 'manual gap',
    expected_minutes: override || gap, max_gap_minutes: inferred, limit_minutes: override || inferred,
    saves_success: !(w.settings && w.settings.saveDataSuccessExecution === 'none'),
    updated_at: w.updatedAt, row,
  } });
}
return out;

// Judges each workflow: stalled, failing, empty, or recovered. Outputs only rows whose state changed.
const s = $('Watch settings').first().json;
const now = Date.now();
const plan = $('Work out the schedules').all().map(i => i.json);
const execs = $('Get recent executions').all().map(i => i.json).filter(e => e && e.id && e.mode !== 'manual');
const runs = $('Get recent runs').all().map(i => i.json).filter(r => r && r.workflow_id);
const fmt = m => m >= 2880 ? Math.round(m / 1440) + ' days' : m >= 120 ? Math.round(m / 60) + ' h' : m >= 60 ? '1 h ' + (m - 60) + ' min' : m + ' min';
const link = id => s.n8n_url ? ' <' + s.n8n_url.replace(/\/$/, '') + '/workflow/' + id + '/executions|Executions>' : '';

const out = [];
for (const p of plan) {
  const row = p.row || {};
  const mine = execs.filter(e => String(e.workflowId) === p.workflow_id);
  const last = Math.max(0, ...mine.map(e => Date.parse(e.startedAt) || 0));
  const since = last || Date.parse(p.updated_at) || now;            // never ran: count from when it was last saved
  const idle = Math.floor((now - since) / 60000);
  const fails = mine.filter(e => ['error', 'crashed'].includes(e.status) && Date.parse(e.startedAt) > now - 3600e3).length;
  const minItems = Number(row.min_items) > 0 ? Number(row.min_items) : null;
  const k = Number(row.empty_runs_before_alert) > 0 ? Number(row.empty_runs_before_alert) : 3;
  const recent = runs.filter(r => String(r.workflow_id) === p.workflow_id || (!r.workflow_id && r.workflow_name === p.workflow_name))
                     .sort((a, b) => Date.parse(b.ran_at) - Date.parse(a.ran_at)).slice(0, k);

  let issue = '', line = '';
  if (p.saves_success && p.limit_minutes && idle > p.limit_minutes) {
    issue = 'stalled';
    line = last ? `no run for ${fmt(idle)} (expected every ${fmt(p.expected_minutes)})` : `no run in the ${fmt(idle)} since it was last saved`;
  } else if (fails >= s.failing_threshold) {
    issue = 'failing'; line = `${fails} failed runs in the last hour`;
  } else if (minItems && recent.length >= k && recent.every(r => Number(r.items) < minItems)) {
    issue = 'empty'; line = (k === 1 ? 'the last run had ' : `the last ${k} runs all had `) + (minItems === 1 ? 'no items' : `fewer than ${minItems} items (latest: ${Number(recent[0].items)})`);
  }

  const was = row.alerting === true;
  const cooled = !row.last_alert_at || now - Date.parse(row.last_alert_at) > s.cooldown_minutes * 60000;
  let say = '';
  if (issue && (!was || row.alert_kind !== issue || cooled)) say = issue;
  else if (!issue && was) say = 'recovered';

  const changed = !row.workflow_id || row.workflow_name !== p.workflow_name || row.schedule !== p.schedule
    || (Number(row.max_gap_minutes) || null) !== p.max_gap_minutes || say;
  if (!changed) continue;
  out.push({ json: {
    workflow_id: p.workflow_id, workflow_name: p.workflow_name, schedule: p.schedule, max_gap_minutes: p.max_gap_minutes,
    alerting: !!issue, alert_kind: issue,
    last_alert_at: say && say !== 'recovered' ? new Date(now).toISOString() : (row.last_alert_at || null),
    say, line: issue ? line + link(p.workflow_id) : '',
    repeat: !!(say && was && row.alert_kind === say),
  } });
}
return out;

// One message for everything this run found. Nothing to say, no message.
const rows = $('Judge each workflow').all().map(i => i.json).filter(r => r.say);
if (!rows.length) return [];
const icon = { stalled: '🔴', failing: '🟠', empty: '🟡', recovered: '✅' };
const order = ['stalled', 'failing', 'empty', 'recovered'];
rows.sort((a, b) => order.indexOf(a.say) - order.indexOf(b.say));
const bad = rows.filter(r => r.say !== 'recovered');
const lines = rows.map(r => r.say === 'recovered'
  ? `${icon.recovered} *${r.workflow_name}* recovered`
  : `${icon[r.say]} *${r.workflow_name}* ${r.say}${r.repeat ? ' (still)' : ''}: ${r.line}`);
return [{ json: {
  title: bad.length ? `Workflow health: ${bad.length} issue${bad.length > 1 ? 's' : ''}` : 'Workflow health: recovered',
  body: lines.join('\n'),
} }];

// Posts every day. All clear is one line; otherwise what's wrong, the day's failures, and what isn't covered.
const s = $('Digest settings').first().json;
const self = $workflow.id;
const fails = $('Get the last 24 hours of failures').all().map(i => i.json).filter(f => f && f.workflow_id !== undefined && f.id);
const watch = $('Get the watch list').all().map(i => i.json).filter(r => r && r.workflow_id);
const wfs = $('Get workflows for the digest').all().map(i => i.json).filter(w => w && w.id && w.id !== self
  && !(s.ignore_tag && (w.tags || []).some(t => t.name === s.ignore_tag)));
const live = new Set(wfs.map(w => String(w.id)));
const watched = watch.filter(r => r.enabled !== false && live.has(String(r.workflow_id)));
const alerting = watched.filter(r => r.alerting);
const icon = { stalled: '🔴', failing: '🟠', empty: '🟡' };
const clip = (t, n) => { t = String(t || '').replace(/\s+/g, ' '); return t.length > n ? t.slice(0, n - 1) + '…' : t; };

const groups = {};
for (const f of fails) {
  const g = groups[f.workflow_name] = groups[f.workflow_name] || { n: 0, last: f };
  g.n++; if (Date.parse(f.failed_at) > Date.parse(g.last.failed_at)) g.last = f;
}
const names = Object.keys(groups).sort((a, b) => groups[b].n - groups[a].n);
const noHandler = wfs.filter(w => !w.settings || w.settings.errorWorkflow !== self).map(w => w.name);
const noSaves = wfs.filter(w => w.settings && w.settings.saveDataSuccessExecution === 'none').map(w => w.name);
const noGap = watched.filter(r => !(Number(r.max_gap_minutes) > 0) && !(Number(r.override_gap_minutes) > 0)).map(r => r.workflow_name);

const lines = [];
let status = 'ok';
if (!alerting.length && !fails.length) {
  lines.push(`✅ *All clear*: ${watched.length} workflow${watched.length === 1 ? '' : 's'} watched, no failures in the last 24 hours.`);
} else {
  for (const r of alerting) lines.push(`${icon[r.alert_kind] || '🔴'} *${r.workflow_name}* is ${r.alert_kind}`);
  if (names.length) {
    if (alerting.length) lines.push('');
    lines.push(`*Failures in the last 24 hours* (${fails.length})`);
    for (const n of names.slice(0, 10)) {
      const g = groups[n], t = DateTime.fromISO(g.last.failed_at).setZone(s.timezone).toFormat('h:mm a');
      lines.push(`• *${n}*: ${g.n}×, last at ${t}${g.last.node_name ? ' in `' + g.last.node_name + '`' : ''}`);
      lines.push(`    _${clip(g.last.error_message, 160)}_`);
    }
    if (names.length > 10) lines.push(`• and ${names.length - 10} more`);
  }
  lines.push('', `_${watched.length - alerting.length} of ${watched.length} watched workflows are fine._`);
  status = alerting.length || names.some(n => groups[n].n >= 3) ? 'error' : 'warn';
}
const gaps = [];
if (noHandler.length) gaps.push(`${noHandler.length} published workflow${noHandler.length === 1 ? ' has' : 's have'} no error workflow: ${clip(noHandler.join(', '), 300)}`);
if (noSaves.length) gaps.push(`not saving successful runs, so stalls can't be seen: ${clip(noSaves.join(', '), 200)}`);
if (noGap.length) gaps.push(`schedule not understood, set override_gap_minutes: ${clip(noGap.join(', '), 200)}`);
if (gaps.length) lines.push('', '*Not covered*', ...gaps.map(g => '• ' + g));
const head = { ok: '✅', warn: '🟡', error: '🔴' }[status];
return [{ json: { title: `${head} n8n daily health`, body: lines.join('\n').trim(), status } }];
